u7936 ?\u960 \'f0\u8056 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\u8166 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u946 \'e2\u970 \'fa\u946 \'e2\u955 \'eb\u8055 ?(\u959 \'ef\u965 \'f5)\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4(\u8134 ?\u962 \'f2)\plain \f1\lang1033\fs24   | \plain \f2\lang1032\fs24 \u946 \'e2\u970 \'fa\u946 \'e2\u955 \'eb\u970 \'fa\u959 \'ef\u952 \'e8\u8053 ?\u954 \'ea\u951 \'e7\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\plain \f1\lang1033\fs24  (\plain \f2\lang1032\fs24 \u8134 ?\u962 \'f2)\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7937 ?\u947 \'e3\u8055 ?(\u945 \'e1\u962 \'f2)\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u963 \'f3\u959 \'ef\u966 \'f6\u8055 ?(\u945 \'e1\u962 \'f2)\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u945 \'e1\u955 \'eb\u945 \'e1\u953 \'e9\u959 \'ef\u964 \'f4\u8049 ?\u964 \'f4\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u946 \'e2\u945 \'e1\u956 \'ec\u946 \'e2\u953 \'e9\u954 \'ea\u8055 ?\u957 \'ed\u959 \'ef\u965 \'f5,\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7952 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f3\lang1033\fs24 \u8039 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7974 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8055 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u970 \'fa\u957 \'ed\u945 \'e1\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7940 ?\u955 \'eb\u955 \'eb\u945 \'e1\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7952 ?\u954 \'ea\u954 \'ea\u955 \'eb\u951 \'e7\u963 \'f3\u970 \'fa\u945 \'e1\u963 \'f3\u964 \'f4\u970 \'fa\u954 \'ea\u8048 ?\plain \f1\lang1033\fs24   | \plain \f2\lang1032\fs24 \u960 \'f0\u945 \'e1\u961 \'f1\u945 \'e1\u963 \'f3\u951 \'e7\u956 \'ec\u949 \'e5\u953 \'e9\u8061 ?\u956 \'ec\u945 \'e1\u964 \'f4\u945 \'e1\plain \f1\lang1033\fs24   (\plain \f2\la