\pard\sl360\slmult1\fi0\li0\tx420\qj\ri0\sb0\sa0\itap0 \plain \f1\b\i\lang1033\fs24 Lit\plain \f1\lang1033\fs24  \tab \plain \f1\scaps\lang1033\fs24 Nachtrag I/Prommer,\plain \f1\lang1033\fs24   f. 131r. \endash  \plain \f1\scaps\lang1033\fs24 H\u246 \'f6rwarth\plain \f1\lang1033\fs24 , S. 16. \endash  \plain \f1\scaps\lang1033\fs24 Hardt\plain \f1\lang1033\fs24   II, S. 253-258. \endash  \plain \f1\scaps\lang1033\fs24 Pitra\plain \f1\lang1033\fs24 , Ius I, S. XIV. \endash  \plain \f1\scaps\lang1033\fs24 Krumbacher\plain \f1\lang1033\fs24 , S. 119. \endash  \plain \f1\scaps\lang1033\fs24 Reil\plain \f1\lang1033\fs24 , Akzentuation, S. 477, 488, 493, 502, 504, 506, 509, 521, 525. \endash  \plain \f1\scaps\lang1033\fs24 Sp. Lampros\plain \f1\lang1033\fs24 , in: NE 17 (1923), S. 97. \endash  \plain \f1\scaps\lang1033\fs24 M. Manoussakas\plain \f1\lang1033\fs24 , Recherches sur la vie de Jean Plousiadenos, in: REB 17 (1959), S. 28 (Anm. 6), 49 (mit Anm. 17). \endash  \plain \f1\scaps\lang1033\fs24 Ders.\plain \f1\lang1033\fs24 , \plain \f2\lang1032\fs24 \u8127 ?\u913 \'c1\u961 \'f1\u967 \'f7\u953 \'e9\u949 \'e5\u961 \'f1\u949 \'e5\u8150 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u924 \'cc\u949 \'e5\u952 \'e8\u8061 ?\u957 \'ed\u951 \'e7\u962 \'f2,\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u922 \'ca\u959 \'ef\u961 \'f1\u8061 ?\u957 \'ed\u951 \'e7\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u924 \'cc\u959 \'ef\u957 \'ed\u949 \'e5\u956 \'ec\u946 \'e2\u945 \'e1\u963 \'f3\u8055 ?\u945 \'e1\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u947 \'e3\u8059 ?\u961 \'f1\u969 \'f9\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u963 \'f3\u964 \'f4\u8048 ?\plain \f1\lang1033\fs24   1500, in: \plain \f2\lang1032\fs24 \u928 \'d0\u949 \'e5\u955 \'eb\u959 \'ef\u960 \'f0\u959 \'ef\u957 \'ed\u957 \'ed\u951 \'e7\u963 \'f3\u953 \'e9\u945 \'e1\u954 \'ea\u8049 ?\plain \f1\lang1033\fs24   3-4 (1960), S. 99 (Anm. 5). \endash  \plain \f1\scaps\lang1033\fs24 Ders.\plain \f1\lang1033\fs24 , \plain \f2\lang1032\fs24 \u8190 ?\u919 \'c7\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u967 \'f7\u949 \'e5\u953 \'e9\u961 \'f1\u959 \'ef\u964 \'f4\u959 \'ef\u957 \'ed\u8055 ?\u945 \'e1\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7985 ?\u949 \'e5\u961 \'f1\u8051 ?\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u8134 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u922 \'ca\u961 \'f1\u8053 ?\u964 \'f4\u951 \'e7\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7936 ?\u960 \'f0\u8056 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u8056 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u956 \'ec\u951 \'e7\u964 \'f4\u961 \'f1\u959 \'ef\u960 \'f0\u959 \'ef\u955 \'eb\u8055 ?\u964 \'f4\u951 \'e7\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u922 \'ca\u959 \'ef\u961 \'f1\u8055 ?\u957 \'ed\u952 \'e8\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 (\u7956 ?\u947 \'e3\u947 \'e3\u961 \'f1\u945 \'e1\u966 \'f6\u945 \'e1\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\u8166 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u953 \'e9\u962 \'f2\plain \f3\lang1033\fs24 \u8189 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u945 \'e1\u7984 ?\u8182 ?\u957 \'ed\u945 \'e1),\plain \f1\lang1033\fs24   in: \plain \f2\lang1032\fs24 \u916 \'c4\u949 \'e5\u955 \'eb\u964 \'f4\u8055 ?\u959 \'ef\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u8134 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u935 \'d7\u961 \'f1\u953 \'e9\u963 \'f3\u964 \'f4\u953 \'e9\u945 \'e1\u957 \'ed\u953 \'e9\u954 \'ea\u8134 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u8127 ?\u913 \'c1\u961 \'f1\u967 \'f7\u945 \'e1\u953 \'e9\u959 \'ef\u955 \'eb\u959 \'ef\u947 \'e3\u953 \'e9\u954 \'ea\u8134 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u8190 ?\u917 \'c5\u964 \'f4\u945 \'e1\u953 \'e9\u961 \'f1\u949 \'e5\u8055 ?\u945 \'e1\u962 \'f2\plain \f1\lang1033\fs24   4 (1964/1965), S. 317-330. \endash  \plain \f1\scaps\lang1033\fs24 Carter\plain \f1\lang1033\fs24 , S. 55-56 (Nr. 60). \endash  \plain \f1\scaps\lang1033\fs24 Voicu\plain \f1\lang1033\fs24 , S. 433. \endash  \plain \f1\scaps\lang1033\fs24 Tinnefeld\plain \f1\lang1033\fs24 , S. <326>, 332-333. \endash  \plain \f1\scaps\lang1033\fs24 A. Pi\u233 \'e9dagnel \endash  L. Doutreleau\plain \f1\lang1033\fs24   (Hrsg.), Jean Chrysostome. Trois cat\u233 \'e9ch\u232 \'e8ses baptismales (SC 366), Paris 1990, S. 74, 82-83 (kurze Beschreibung der Hs.), 89-98 (Text\u252 \'fcberlieferung), 108, 110-111. \endash  \plain \f1\scaps\lang1033\fs24 A.-M. Malingrey\plain \f1\lang1033\fs24   (Hrsg.), Jean Chrysostome. Sur l\rquote \u233 \'e9galit\u233 \'e9 du P\u232 \'e8re et du Fils. Contre les Anom\u233 \'e9ens hom\u233 \'e9lies VII\endash XII (SC 396), Paris 1994, S. 61, 64-65, 68, <106> (Hs. f\u228 \'e4lschlich \u8222 \'84Cod. Mosquensis gr. 190\ldblquote  in der Sigelliste genannt), <107> (\plain \f1\i\lang1033\fs24  Stemma codicum\plain \f1\lang1033\fs24 ). \endash  \plain \f1\scaps\lang1033\fs24 Hajd\u250 \'fa\plain \f1\lang1033\fs24 , Darmarios, S. 125. \endash  \plain \f1\scaps\lang1033\fs24 Tiftixoglu\plain \f1\lang1033\fs24 , Zwei Bearbeiter, S. 133-134. \endash  \plain \f1\scaps\lang1033\fs24 W. Pradels \endash  R. Br\u228 \'e4ndle \endash  M. Heimgartner\plain \f1\lang1033\fs24 , Das bisher vermisste Textst\u252 \'fcck in Johannes Chrysostomus, Adversus Judaeos, Oratio 2, in: Zeitschrift f\u252 \'fcr Antikes Christentum 5 (2001), S. <23> (Anm. 3), 24.}

