?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u961 \'f1\u965 \'f5\u960 \'f0\u964 \'f4\u8057 ?\u956 \'ec\u949 \'e5\u957 \'ed\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\u8166 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u935 \'d7\u961 \'f1\u953 \'e9\u963 \'f3\u964 \'f4\u959 \'ef\u8166 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u964 \'f4\u955 \'eb.\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  des. mut.\plain \f1\lang1033\fs24   S. 465, 26 \plain \f2\lang1032\fs24 \u964 \'f4\u8055 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7936 ?\u960 \'f0\u959 \'ef\u954 \'ea\u965 \'f5\u955 \'eb\u8055 ?\u963 \'f3\u949 \'e5\u953 \'e9\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u8056 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u955 \'eb\u8055 ?\u952 \'e8\u959 \'ef\u957 \'ed.\plain \f1\lang1033\fs24   \endash  Vgl. Cod.graec. 262, Nr. 2.}

