\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u8049 ?\u957 \'ed\u964 \'f4\u945 \'e1\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7952 ?\u960 \'f0\u953 \'e9\u964 \'f4\u965 \'f5\u967 \'f7\u949 \'e5\u8150 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u967 \'f7\u8049 ?\u961 \'f1\u953 \'e9\u964 \'f4\u953 \'e9\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u966 \'f6\u953 \'e9\u955 \'eb\u945 \'e1\u957 \'ed\u952 \'e8\u961 \'f1\u969 \'f9\u960 \'f0\u8055 ?\u8115 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\u8166 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u965 \'f5\u961 \'f1\u8055 ?\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7969 ?\u956 \'ec\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u964 \'f4\u955 \'eb.\plain \f1\lang1033\fs24   \endash  Davor: (ff. 399v-401r) Prooemium; \plain \f1\i\lang1033\fs24  inc.\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u928 \'d0\u959 \'ef\u955 \'eb\u955 \'eb\u959 \'ef\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u956 \'ec\u8050 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7940 ?\u955 \'eb\u955 \'eb\u945 \'e1\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u949 \'e5\u952 \'e8\u8053 ?\u960 \'f0\u945 \'e1\u963 \'f3\u8055 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u949 \'e5\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7952 ?\u954 \'ea\u952 \'e8\plain \f1\lang1033\fs24  <\plain \f2\lang1032\fs24 \u949 \'e5\plain \f1\lang1033\fs24  >\plain \f2\lang1032\fs24 \u953 \'e9\u8049 ?\u950 \'e6\u959 \'ef\u965 \'f5\u963 \'f3\u953 \'e9\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u964 \'f4\u955 \'eb.\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  des.\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u964 \'f4\u8048 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u8056 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7936 ?\u957 \'ed\u952 \'e8\u961 \'f1\u8061 ?\u960 \'f0\u953 \'e9\u957 \'ed\u959 \'ef\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u8033 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u948 \'e4\u951 \'e7\u955 \'eb\u8061 ?\u963 \'f3\u949 \'e5\u953 \'e9\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u8048 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u957 \'ed\u8166 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7936 ?\u957 \'ed\u945 \'e1\u947 \'e3\u957 \'ed\u969 \'f9\u963 \'f3\u952 \'e8\u951 \'e7\u963 \'f3\u8057 ?\u956 \'ec\u949 \'e5\u957 \'ed\u945 \'e1\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u949 \'e5\u8016 ?\u945 \'e1\u947 \'e3\u947 \'e3\u949 \'e5\u955 \'eb\u953 \'e9\u954 \'ea\u8048 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u8165 ?\u951 \'e7\u964 \'f4\u8048 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u959 \'ef\u8021 ?\u964 \'f4\u969 \'f9\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7956 ?\u967 \'f7\u959 \'ef\u957 \'ed\u964 \'f4\u945 \'e1.}

