\pard\sl360\slmult1\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 33. \plain \f1\lang1033\fs24  (ff. 108r-111r) In dominicam XIV Matthaei (Ms. \plain \f2\lang1032\fs24 \u922 \'ca\u965 \'f5\u961 \'f1\u953 \'e9\u945 \'e1\u954 \'ea\u951 \'e7\plain \f3\lang1033\fs24 `\plain \f4\lang1033\fs24 \u837 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u953 \'e9\u948 \'e4\plain \f1\lang1033\fs24  \u180 \'b4 \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\plain \f4\lang1033\fs24 \u8166 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u924 \'cc\u945 \'e1\u964 \'f4\u952 \'e8\u945 \'e1\u8055 ?\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24 ); \plain \f1\i\lang1033\fs24  inc.\plain \f1\lang1033\fs24   (nach der Perikope Matth. 22, 1-9) \plain \f2\lang1032\fs24 \u8142 ?\u913 \'c1\u957 \'ed\u952 \'e8\u961 \'f1\u969 \'f9\u960 \'f0\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u946 \'e2\u945 \'e1\u963 \'f3\u953 \'e9\u955 \'eb\u949 \'e5\u8058 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u955 \'eb\u8051 ?\u947 \'e3\u949 \'e5\u964 \'f4\u945 \'e1\u953 \'e9\plain \f1\lang1033\fs24   \plain \f4\lang1033\fs24 \u8001 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u920 \'c8\u949 \'e5\u8056 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u945 \'e1\u964 \'f4\u8053 ?\u961 \'f1,\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u957 \'ed\u8059 ?\u956 \'ec\u966 \'f6\u953 \'e9\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u948 \'e4\u8050 ?\plain \f1\lang1033\fs24   \plain \f4\lang1033\fs24 \u8001 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u8017 ?\u953 \'e9\u8056 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u955 \'eb\u8057 ?\u947 \'e3\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u945 \'e1\u8016 ?\u964 \'f4\u959 \'ef\plain \f4\lang1033\fs24 \u8166 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u964 \'f4\u955 \'eb.\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  des\plain \f1\lang1033\fs24 . \plain \f2\lang1032\fs24 \u956 \'ec\u949 \'e5\u964 \'f4\u8048 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u963 \'f3\u960 \'f0\u959 \'ef\u965 \'f5\u948 \'e4\u8134 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u8052 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u946 \'e2\u945 \'e1\u963 \'f3\u953 \'e9\u955 \'eb\u949 \'e5\u8055 ?\u945 \'e1\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7937 ?\u961 \'f1\u960 \'f0\u8049 ?\u950 \'e6\u959 \'ef\u957 \'ed\u964 \'f4\u949 \'e5\u962 \'f2,\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7989 ?\u957 \'ed\u945 \'e1\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7936 ?\u954 \'ea\u951 \'e7\u961 \'f1\u8049 ?\u964 \'f4\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7936 ?\u947 \'e3\u945 \'e1\u952 \'e8\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7936 ?\u960 \'f0\u959 \'ef\u955 \'eb\u945 \'e1\u8059 ?\u963 \'f3\u969 \'f9\u956 \'ec\u949 \'e5\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7952 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u935 \'d7\u961 \'f1\u953 \'e9\u963 \'f3\u964 \'f4\u969 \'f9\plain \f3\lang1033\fs24 `\plain \f4\lang1033\fs24 \u837 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u8127 ?\u921 \'c9\u951 \'e7\u963 \'f3\u959 \'ef\plain \f4\lang1033\fs24 \u8166 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u969 \'f9\plain \f3\lang1033\fs24 `\plain \f4\lang1033\fs24 \u837 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u922 \