'e9\u963 \'f3\u964 \'f4\u959 \'ef\u8166 ?,\plain \f1\lang1033\fs24   \plain \f4\lang1033\fs24 \u8103 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u961 \'f1\u8051 ?\u960 \'f0\u949 \'e5\u953 \'e9\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u964 \'f4\u955 \'eb.}

