fs24 . \plain \f2\lang1032\fs24 \u959 \'ef\u8021 ?\u964 \'f4\u969 \'f9\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7952 ?\u955 \'eb\u960 \'f0\u8055 ?\u950 \'e6\u959 \'ef\u956 \'ec\u949 \'e5\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u956 \'ec\u949 \'e5\u955 \'eb\u955 \'eb\u8057 ?\u957 \'ed\u964 \'f4\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7952 ?\u954 \'ea\u949 \'e5\u8055 ?\u957 \'ed\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7936 ?\u970 \'fa\u948 \'e4\u8055 ?\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7936 ?\u947 \'e3\u945 \'e1\u952 \'e8\plain \f4\lang1033\fs24 \u8182 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7952 ?\u960 \'f0\u953 \'e9\u964 \'f4\u949 \'e5\u8059 ?\u958 \'ee\u949 \'e5\u963 \'f3\u952 \'e8\u945 \'e1\u953 \'e9\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u967 \'f7\u8049 ?\u961 \'f1\u953 \'e9\u964 \'f4\u953 \'e9\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u966 \'f6\u953 \'e9\u955 \'eb\u945 \'e1\u957 \'ed\u952 \'e8\u961 \'f1\u969 \'f9\u960 \'f0\u8055 ?\u8115 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\plain \f4\lang1033\fs24 \u8166 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u922 \'ca\u965 \'f5\u961 \'f1\u8055 ?\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7969 ?\u956 \'ec\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u8127 ?\u921 \'c9\u951 \'e7\u963 \'f3\u959 \'ef\plain \f4\lang1033\fs24 \u8166 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u935 \'d7\u961 \'f1\u953 \'e9\u963 \'f3\u964 \'f4\u959 \'ef\u8166 ?\plain \f4\lang1033\fs24 ,