'e7\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u8000 ?\u961 \'f1\u947 \'e3\u8052 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7936 ?\u966 \'f6\u8127 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7969 ?\u956 \'ec\plain \f4\lang1033\fs24 \u8182 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7936 ?\u960 \'f0\u959 \'ef\u961 \'f1\u961 \'f1\u8055 ?\u968 \'f8\u969 \'f9\u956 \'ec\u949 \'e5\u957 \'ed\plain \f1\lang1033\fs24   \plain \f4\lang1033\fs24 ...\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7952 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u935 \'d7\u961 \'f1\u953 \'e9\u963 \'f3\u964 \'f4\plain \f4\lang1033\fs24 \u8183 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u8127 ?\u921 \'c9\u951 \'e7\u963 \'f3\u959 \'ef\plain \f4\lang1033\fs24 \u8166 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u969 \'f9\plain \f3\lang1033\fs24 `\plain \f4\lang1033\fs24 \u837 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u922 \'ca\u965 \'f5\u961 \'f1\u8055 ?\u8179 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7969 ?\u956 \'ec\plain \f4\lang1033\fs24 \u8182 ?\plain \f2\lang1032\fs24 \u957 \'ed,\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u8103 ? \u960 \'f0\u961 \'f1\u8051 ?\u960 \'f0\u949 \'e5\u953 \'e9\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u948 \'e4\u8057 ?\u958 \'ee\u945 \'e1\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u964 \'f4\u955 \'eb.}

