\pard\sl360\slmult1\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 48. \plain \f1\lang1033\fs24  (ff. 169r-172v) In dominicam XIII Lucae (Ms. \plain \f2\lang1032\fs24 \u922 \'ca\u965 \'f5\u961 \'f1\u953 \'e9\u945 \'e1\u954 \'ea\u951 \'e7\plain \f3\lang1033\fs24 `\plain \f4\lang1033\fs24 \u837 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u953 \'e9\u947 \'e3\plain \f1\lang1033\fs24  \u180 \'b4 \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\plain \f4\lang1033\fs24 \u8166 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u923 \'cb\u959 \'ef\u965 \'f5\u954 \'ea\plain \f4\lang1033\fs24 \u8118 ?\plain \f1\lang1033\fs24 ); \plain \f1\i\lang1033\fs24  inc.\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u927 \'cf\u7985 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\u8058 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7936 ?\u947 \'e3\u961 \'f1\u959 \'ef\u8058 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\plain \f4\lang1033\fs24 \u8182 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7936 ?\u957 \'ed\u952 \'e8\u961 \'f1\u8061 ?\u960 \'f0\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u966 \'f6\u965 \'f5\u955 \'eb\u8049 ?\u963 \'f3\u963 \'f3\u959 \'ef\u957 \'ed\u964 \'f4\u949 \'e5\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u947 \'e3\u949 \'e5\u969 \'f9\u961 \'f1\u947 \'e3\u959 \'ef\u8055 ?,\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u8005 ?\u963 \'f3\u945 \'e1\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7952 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u945 \'e1\u8016 ?\u964 \'f4\u959 \'ef\plain \f4\lang1033\fs24 \u8150 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7956 ?\u967 \'f7\u959 \'ef\u965 \'f5\u963 \'f3\u953 \'e9\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\plain \f4\lang1033\fs24 \u8182 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7936 ?\u957 \'ed\u952 \'e8\u8051 ?\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u964 \'f4\u955 \'eb.\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  des\plain \f1\lang1033\fs24 . \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u948 \'e4\u953 \'e9\u954 \'ea\u945 \'e1\u8055 ?\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u8001 ?\u956 \'ec\u951 \'e7\u947 \'e3\u8059 ?\u961 \'f1\u949 \'e5\u969 \'f9\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u8059 ?\u967 \'f7\u969 \'f9\u956 \'ec\u949 \'e5\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\plain \f4\lang1033\fs24 \u8182 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7936 ?\u954 \'ea\u951 \'e7\u961 \'f1\u8049 ?\u964 \'f4\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7952 ?\u954 \'ea\u949 \'e5\u8055 ?\u957 \'ed\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7936 ?\u966 \'f6\u961 \'f1\u8049 ?\u963 \'f3\u964 \'f4\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7936 ?\u947 \'e3\u945 \'e1\u952 \'e8\plain \f4\lang1033\fs24 \u8182 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24   \plain \f4\lang1033\fs24 ...\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u949 \'e5\u7984 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\u8058 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u945 \'e1\u7984 ?\plain \f4\lang1033\fs24 \u8182 ?\plain \f2\lang1032\fs24 \u957 \'ed\u945 \'e1\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\plain \f4\lang1033\fs24 \u8182 ?\plain \f2\lang1032\fs24 \u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u945 \'e1\u7984 ?\u8061 ?\u957 \'ed\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7936 ?\u956 \'ec\u8053 ?\u957 \'ed,\plain \f5\lang1024\fs24  \plain \f1\lang1033\fs24  vgl. \plain \f1\scaps\lang1033\fs24 Ehrhard\plain \f1\lang1033\fs24 , \u220 \'dcberlieferung III, S. 561 (Nr. 34).}

