\pard\sl360\slmult1\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\scaps\lang1033\fs24 50. \plain \f1\lang1033\fs24  (ff. 176v-181r) In dominicam XV Lucae (Ms. \plain \f2\lang1032\fs24 \u922 \'ca\u965 \'f5\u961 \'f1\u953 \'e9\u945 \'e1\u954 \'ea\u951 \'e7\plain \f3\lang1033\fs24 `\plain \f4\lang1033\fs24 \u837 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u953 \'e9\u948 \'e4\plain \f1\lang1033\fs24  \u180 \'b4 [!] \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\plain \f4\lang1033\fs24 \u8166 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u923 \'cb\u959 \'ef\u965 \'f5\u954 \'ea\plain \f4\lang1033\fs24 \u8118 ?\plain \f1\lang1033\fs24 ); \plain \f1\i\lang1033\fs24  inc.\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u928 \'d0\u8118 ?\u963 \'f3\u945 \'e1\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u956 \'ec\u8050 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7936 ?\u948 \'e4\u953 \'e9\u954 \'ea\u8055 ?\u945 \'e1\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7937 ?\u961 \'f1\u960 \'f0\u945 \'e1\u947 \'e3\u8052 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u955 \'eb\u949 \'e5\u959 \'ef\u957 \'ed\u949 \'e5\u958 \'ee\u8055 ?\u945 \'e1\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u954 \'ea\u8052 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u954 \'ea\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u954 \'ea\u8055 ?\u963 \'f3\u964 \'f4\u951 \'e7\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u964 \'f4\u955 \'eb.\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  des\plain \f1\lang1033\fs24 . \plain \f2\lang1032\fs24 \u7952 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u951 \'e7\plain \f3\lang1033\fs24 `\plain \f4\lang1033\fs24 \u837 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7969 ?\u956 \'ec\u8051 ?\u961 \'f1\u8115 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\plain \f4\lang1033\fs24 \u8134 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u948 \'e4\u953 \'e9\u954 \'ea\u945 \'e1\u8055 ?\u945 \'e1\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u945 \'e1\u8016 ?\u964 \'f4\u959 \'ef\plain \f4\lang1033\fs24 \u8166 ? \plain \f2\lang1032\fs24 \u7936 ?\u957 \'ed\u964 \'f4\u945 \'e1\u960 \'f0\u959 \'ef\u948 \'e4\u8057 ?\u963 \'f3\u949 \'e5\u969 \'f9\u962 \'f2\plain \f1\lang1033\fs24   \plain \f4\lang1033\fs24 ...\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u945 \'e1\u7984 ?\u969 \'f9\u957 \'ed\u8055 ?\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7936 ?\u960 \'f0\u959 \'ef\u955 \'eb\u945 \'e1\u8059 ?\u963 \'f3\u969 \'f9\u956 \'ec\u949 \'e5\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7936 ?\u947 \'e3\u945 \'e1\u952 \'e8\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u967 \'f7\u8049 ?\u961 \'f1\u953 \'e9\u964 \'f4\u953 \'e9\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u966 \'f6\u953 \'e9\u955 \'eb\u945 \'e1\u957 \'ed\u952 \'e8\u961 \'f1\u969 \'f9\u960 \'f0\u8055 ?\u8115 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u964 \'f4\u955 \'eb.}

