\'f4\u953 \'e9\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\plain \f4\lang1033\fs24 \u8166 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7936 ?\u955 \'eb\u951 \'e7\u952 \'e8\u953 \'e9\u957 \'ed\u959 \'ef\plain \f4\lang1033\fs24 \u8166 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u935 \'d7\u961 \'f1\u953 \'e9\u963 \'f3\u964 \'f4\u959 \'ef\plain \f4\lang1033\fs24 \u8166 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\plain \f4\lang1033\fs24 \u8166 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u920 \'c8\u949 \'e5\u959 \'ef\plain \f4\lang1033\fs24 \u8166 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u963 \'f3\u969 \'f9\u964 \'f4\plain \f4\lang1033\fs24 \u8134 ?\plain \f2\lang1032\fs24 \u961 \'f1\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7969 ?\u956 \'ec\plain \f4\lang1033\fs24 \u8182 ?\plain \f2\lang1032\fs24 \u957 \'ed,\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u8005 ?\u964 \'f4\u953 \'e9\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u945 \'e1\u8016 ?\u964 \'f4\u969 \'f9\plain \f3\lang1033\fs24 `\plain \f4\lang1033\fs24 \u837 ?\plain \f1\lang1033\fs24   \plain \f4\lang1033\fs24 \u7969 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u948 \'e4\u8057 ?\u958 \'ee\u945 \'e1\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u964 \'f4\u955 \'eb.\plain \f5\lang1024\fs24 , \plain \f1\lang1033\fs24  vgl. \plain \f1\scaps\lang1033\fs24 Ehrhard\plain \f1\lang1033\fs24 , \u220 \'dcberlieferung III, S. 563 (Nr. 54); BHG 1906p mit Nov. Auct.; Cod.graec. 196, ff. 633r-638r.}

