\pard\sl360\slmult1\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  (ff. 1v-2v) Evangelium nach \plain \f1\b\lang1033\fs24  Matthaeus\plain \f1\lang1033\fs24   1, 1-3, 2 (Ms. \plain \f2\lang1032\fs24 \u917 \'c5\u8016 ?\u945 \'e1\u947 \'e3\u947 \'e3\u8051 ?\u955 \'eb\u953 \'e9\u959 \'ef\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u964 \'f4\u8048 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u924 \'cc\u945 \'e1\u964 \'f4\u952 \'e8\u945 \'e1\u8150 ?\u959 \'ef\u957 \'ed\plain \f1\lang1033\fs24 ); \plain \f1\i\lang1033\fs24  inc.\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u914 \'c2\u8055 ?\u946 \'e2\u955 \'eb\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u947 \'e3\u949 \'e5\u957 \'ed\u8051 ?\u963 \'f3\u949 \'e5\u969 \'f9\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u8127 ?\u921 \'c9\u951 \'e7\u963 \'f3\u959 \'ef\u8166 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u935 \'d7\u961 \'f1\u953 \'e9\u963 \'f3\u964 \'f4\u959 \'ef\u8166 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u964 \'f4\u955 \'eb.\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  des.\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7952 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u8135 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7952 ?\u961 \'f1\u8053 ?\u956 \'ec\u8179 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u8134 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u8127 ?\u921 \'c9\u959 \'ef\u965 \'f5\u948 \'e4\u945 \'e1\u8055 ?\u945 \'e1\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u955 \'eb\u8051 ?\u947 \'e3\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24  \u183 \'b7 \plain \f2\lang1032\fs24 \u956 \'ec\u949 \'e5\u964 \'f4\u945 \'e1\u957 \'ed\u959 \'ef\u949 \'e5\u8150 ?\u964 \'f4\u949 \'e5\plain \f1\lang1033\fs24 .}

