57 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u948 \'e4\u8050 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\u8166 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u935 \'d7\u961 \'f1\u953 \'e9\u963 \'f3\u964 \'f4\u959 \'ef\u8166 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u949 \'e5\u8016 ?\u963 \'f3\u8051 ?\u946 \'e2\u949 \'e5\u953 \'e9\u945 \'e1\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u949 \'e5\u954 \'ea\u964 \'f4\u951 \'e7\u956 \'ec\u8051 ?\u957 \'ed\u959 \'ef\u965 \'f5\u962 \'f2\plain \f1\lang1033\fs24 . 
