 \plain \f2\lang1032\fs24 \u967 \'f7\u961 \'f1\u8057 ?\u957 \'ed\u959 \'ef\u965 \'f5\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u953 \'e9\u949 \'e5\plain \f3\lang1033\fs24 \u8189 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u8134 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\u8166 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u935 \'d7\u961 \'f1\u953 \'e9\u963 \'f3\u964 \'f4\u959 \'ef\u8166 ?\plain \f1\lang1033\fs24   \plain \f3\lang1033\fs24 \u7936 ?\plain \f2\lang1032\fs24 \u957 \'ed\u945 \'e1\u955 \'eb\u8053 ?\u968 \'f8\u949 \'e5\u969 \'f9\u962 \'f2\plain \f1\lang1033\fs24  \u183 \'b7 \plain \f2\lang1032\fs24 \u7956 ?\u967 \'f7\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u963 \'f3\u964 \'f4\u8055 ?\u967 \'f7\u959 \'ef\u965 \'f5\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u948 \'e4\u953 \'e9\u963 \'f3\u967 \'f7\u953 \'e9\u955 \'eb\u8055 ?\u959 \'ef\u965 \'f5\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u8000 ?\u954 \'ea\u964 \'f4\u945 \'e1\u954 \'ea\u959 \'ef\u963 \'f3\u8055 ?\u959 \'ef\u965 \'f5\u962 \'f2.}

