033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u949 \'e5\u961 \'f1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u8048 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u8001 ?\u956 \'ec\u969 \'f9\u957 \'ed\u965 \'f5\u956 \'ec\u8055 ?\u945 \'e1\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u948 \'e4\u953 \'e9\u945 \'e1\u964 \'f4\u961 \'f1\u8055 ?\u946 \'e2\u959 \'ef\u957 \'ed\u964 \'f4\u945 \'e1\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u964 \'f4\u955 \'eb\plain \f1\lang1033\fs24 . \plain \f1\i\lang1033\fs24  des.\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u961 \'f1\u8056 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\u8020 ?\u957 \'ed\u959 \'ef\u956 \'ec\u945 \'e1\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u8004 ?\u957 \'ed\u964 \'f4\u949 \'e5\u962 \'f2\plain \f1\lang1033\fs24 , ed. \plain \f1\scaps\lang1033\fs24 Ebbesen\plain \f1\lang1033\fs24 , S. 74-75.}

