u8053 ?\u947 \'e3\u951 \'e7\u963 \'f3\u953 \'e9\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u956 \'ec\u949 \'e5\u961 \'f1\u953 \'e9\u954 \'ea\u8053 ?\u183 \'b7\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u955 \'eb\u8057 ?\u947 \'e3\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u945 \'e1\plain \f3\lang1033\fs24 \u8189 ?\u183 \'b7\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u956 \'ec\u951 \'e7\u957 \'ed\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u924 \'cc\u945 \'e1\u8055 ?\u8179 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7984 ?\u957 \'ed(\u948 \'e4\u953 \'e9\u954 \'ea\u964 \'f4\u953 \'e9\u8182 ?\u957 \'ed\u959 \'ef\u962 \'f2)\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u950 \'e6\plain \f3\lang1033\fs24 \u8189 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7956 ?\u964 \'f4\u959 \'ef\u965 \'f5\u962 \'f2\plain \f1\lang1033\fs24   \plain \f4\lang1033\fs24 \u203 \'cb\u245 \'f5\plain \f2\lang1032\fs24 \u968 \'f8\u959 \'ef\u946 \'e2\plain \f3\lang1033\fs24 \u8189 ?\plain \f1\lang1033\fs24 ). \endash  (ff. 237v-253r) Buch 2 (Ms. <\plain \f2\lang1032\fs24 \u932 \'d4\plain \f1\lang1033\fs24  >\plain \f2\lang1032\fs24 \u959 \'ef\u8166 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u945 \'e1\u8016 ?\u964 \'f4\u959 \'ef\u8166 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u949 \'e5\u961 \'f1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u964 \'f4\plain \f3\lang1033\fs24 \u8127 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u945 \'e1\u8016 ?\u964 \'f4\u8056 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u956 \'ec\u949 \'e5\u961 \'f1\u953 \'e9\u954 \'ea\u8052 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u948 \'e4\u953 \'e9\u8053 ?\u947 \'e3\u951 \'e7\u963 \'f3\u953 \'e9\u962 \'f2\u183 \'b7\plain \f1\lang1033\fs2