948 \'e4\u953 \'e9\u954 \'ea\u964 \'f4\u953 \'e9\u8182 ?\u957 \'ed\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24   \plain \f4\lang1033\fs24 \u245 \'f5\plain \f3\lang1033\fs24 \u8189 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7956 ?\u964 \'f4\u959 \'ef\u965 \'f5\u962 \'f2\plain \f1\lang1033\fs24   \plain \f4\lang1033\fs24 \u203 \'cb\u245 \'f5\plain \f2\lang1032\fs24 \u968 \'f8\u959 \'ef\u945 \'e1\plain \f3\lang1033\fs24 \u8189 ?\plain \f1\lang1033\fs24 ), ediert in: \plain \f2\lang1032\fs24 \u925 \'cd\u953 \'e9\u954 \'ea\u951 \'e7\u966 \'f6\u8057 ?\u961 \'f1\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u956 \'ec\u959 \'ef\u957 \'ed\u945 \'e1\u963 \'f3\u964 \'f4\u959 \'ef\u8166 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u961 \'f1\u949 \'e5\u963 \'f3\u946 \'e2\u965 \'f5\u964 \'f4\u8051 ?\u961 \'f1\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\u8166 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u914 \'c2\u955 \'eb\u949 \'e5\u956 \'ec\u956 \'ec\u8055 ?\u948 \'e4\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7952 ?\u960 \'f0\u953 \'e9\u964 \'f4\u959 \'ef\u956 \'ec\u8052 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u955 \'eb\u959 \'ef\u947 \'e3\u953 \'e9\u954 \'ea\u8134 ?\u962 \'f2\plain \f1\lang1033\fs24   \u8230 \'85 \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u949 \'e5\u961 \'f1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u963 \'f3\u8061 ?\u956 \'ec\u945 \'e1\u964 \'f4\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24   \plain \f3\lang1033\fs24 ...\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u949 \'e5\u961 \'f1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u968 \'f8\u965 \'f5\u967 \'f7\u8134 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f3\lang1033\fs24 ...\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u949 \'e5\u961 \'f1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u968 \'f8\u965 \'f5\u967 \'f7\u8134 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7936 ?\u961 \'f1\u949 \'e5\u964 \'f4\u8134 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7936 ?\u963 \'f3\u954 \'ea\u8053 ?\u963 \'f3\u949 \'e5\u969 \'f9\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u964 \'f4\u955 \'eb.\plain \f1\lang1033\fs24 , III, Leipzig 1784, S. 29-48; \plain \f1\i\lang1033\fs24  inc.\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u8190 ?\u919 \'c7\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u956 \'ec\u8050 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u8001 ?\u961 \'f1\u956 \'ec\u8052 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\u8166 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u955 \'eb\u8057 ?\u947 \'e3\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u948 \'e4\u953 \'e9\u945 \'e1\u955 \'eb\u945 \'e1\u946 \'e2\u949 \'e5\u8150 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u949 \'e5\u961 \'f1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u8049 ?\u963 \'f3\u951 \'e7\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u968 \'f8\u965 \'f5\u967 \'f7\u8134 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u964 \'f4\u955 \'eb.\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  des.\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u959 \'ef\u8021 ?\u964 \'f4\u969 \'f9\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24   \plain \f3\lang1033\fs24 \u7969 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u8057 ?\u955 \'eb\u945 \'e1\u963 \'f3\u953 \'e9\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u959 \'ef\u7991 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7938 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u955 \'eb\u951 \'e7\u961 \'f1\u969 \'f9\u952 \'e8\u949 \'e5\u8055 ?\u951 \'e7\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u956 \'ec\u959 \'ef\u957 \'ed\u953 \'e9\u956 \'ec\u8061 ?\u964 \'f4\u945 \'e1\u964 \'f4\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7936 ?\u964 \'f4\u949 \'e5\u955 \'eb\u949 \'e5\u8059 ?\u964 \'f4\u951 \'e7\u964 \'f4\u959 \'ef\u962 \'f2.}

