f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u945 \'e1\u964 \'f4\u961 \'f1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u8183 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u945 \'e1\u957 \'ed\u945 \'e1\u947 \'e3\u8055 ?\u8179 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u950 \'e6\u969 \'f9\u959 \'ef\u960 \'f0\u959 \'ef\u953 \'e9\plain \f3\lang1033\fs24 \u8183 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u957 \'ed\u949 \'e5\u8059 ?\u956 \'ec\u945 \'e1\u964 \'f4\u953 \'e9\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u957 \'ed\u8166 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7936 ?\u949 \'e5\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u949 \'e5\u7984 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\u8058 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u945 \'e1\u7984 ?\u8182 ?\u957 \'ed\u945 \'e1\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u945 \'e1\u7984 ?\u8061 ?\u957 \'ed\u969 \'f9\u957 \'ed.\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7936 ?\u956 \'ec\u8053 ?\u957 \'ed.}

