\'f0\u959 \'ef\u8055 ?\u951 \'e7\u963 \'f3\u949 \'e5\u957 \'ed\plain \f1\lang1033\fs24   \plain \f3\lang1033\fs24 \u8001 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u8127 ?\u921 \'c9\u8061 ?\u946 \'e2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7952 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u8135 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u955 \'eb\u951 \'e7\u947 \'e3\u8135 ?\u183 \'b7\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7936 ?\u960 \'f0(\u8057 ?)\u954 \'ea\u961 \'f1(\u953 \'e9\u963 \'f3\u953 \'e9\u962 \'f2)\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u950 \'e6\plain \f3\lang1033\fs24 \u8189 ?\plain \f1\lang1033\fs24  (\plain \f1\i\lang1033\fs24  sic\plain \f1\lang1033\fs24 ).}

