\pard\sl360\slmult1\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  13. (f. 310r, 11. Z. v. o.-310v, 9. Z. v. o.) \u220 \'dcber das Alter von Maria, Joachim, Anna und Joseph nach dem Zeugnis des alten Hippolytus, eines Freundes der Apostel (Ms. ohne Titel); \plain \f1\i\lang1033\fs24  inc.\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u932 \'d4\u961 \'f1\u953 \'e9\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7952 ?\u964 \'f4\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u961 \'f1\u959 \'ef\u963 \'f3\u8053 ?\u967 \'f7\u952 \'e8\u951 \'e7\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u8183 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u957 \'ed\u945 \'e1\u8183 ?\plain \f1\lang1033\fs24   \plain \f3\lang1033\fs24 \u7969 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u8017 ?\u960 \'f0\u949 \'e5\u961 \'f1\u945 \'e1\u947 \'e3\u8055 ?\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u952 \'e8\u949 \'e5\u959 \'ef\u964 \'f4\u8057 ?\u954 \'ea\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7952 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u8183 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u957 \'ed\u945 \'e1\plain \f3\lang1033\fs24 \u8183 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7952 ?\u960 \'f0\u959 \'ef\u8055 ?\u951 \'e7\u963 \'f3\u949 \'e5\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7956 ?\u964 \'f4\u951 \'e7\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u953 \'e9\u945 \'e1\plain \f3\lang1033\fs24 \u8189 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u964 \'f4\u955 \'eb.\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  des.\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\