\pard\sl360\slmult1\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  14. (ff. 310v, 10. Z. v. o.-311r, 9. Z. v. o.) \u220 \'dcber den Zahlenwert der W\u246 \'f6rter \plain \f2\lang1032\fs24 \u924 \'cc\u969 \'f9\u963 \'f3\u8134 ?\u962 \'f2,\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u935 \'d7\u961 \'f1\u953 \'e9\u963 \'f3\u964 \'f4\u8057 ?\u962 \'f2\plain \f1\lang1033\fs24   und \plain \f2\lang1032\fs24 \u963 \'f3\u964 \'f4\u945 \'e1\u965 \'f5\u961 \'f1\u8057 ?\u962 \'f2\plain \f1\lang1033\fs24   (Ms. ohne Titel); \plain \f1\i\lang1033\fs24  inc.\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u8127 ?\u917 \'c5\u960 \'f0\u949 \'e5\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u8056 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u924 \'cc\u969 \'f9\u963 \'f3\u8134 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u8004 ?\u957 \'ed\u959 \'ef\u956 \'ec\u945 \'e1\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7936 ?\u961 \'f1\u953 \'e9\u952 \'e8\u956 \'ec\u8056 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7956 ?\u967 \'f7\u949 \'e5\u953 \'e9\plain \f1\lang1033\fs24   \plain \f4\lang1033\fs24 \u203 \'cb\plain \f2\lang1032\fs24 \u945 \'e1\u963 \'f3\u956 \'ec\u951 \'e7\plain \f3\lang1033\fs24 \u8189 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u949 \'e5\u8017 ?\u961 \'f1\u8051 ?\u952 \'e8(\plain \f1\lang1033\fs24   \plain \f3\lang1033\fs24 )\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\u963 \'f3\u945 \'e1\u8059 ?\u964 \'f4\u945 \'e1 \u7956 ?\u964 \'f4\u951 \'e7 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24   \plain \f3\lang1033\fs24 \u8001 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u924 \'cc\u969 \'f9\u963 \'f3\u945 \'e1\u970 \'fa\u954 \'ea\u8056 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u957 \'ed\u8057 ?\u956 \'ec\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7972 ?\u961 \'f1\u954 \'