\pard\sl360\slmult1\fi0\li0\qj\ri0\sb0\sa0\itap0 \plain \f1\lang1033\fs24  (f. 2v, 1.-13. Z. v. o.) Preces Lacedaemonii cuiusdam (Ms. \plain \f2\lang1032\fs24 \u917 \'c5\u8016 ?\u967 \'f7\u8052 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u923 \'cb\u945 \'e1\u954 \'ea\u949 \'e5\u948 \'e4\u945 \'e1\u8055 ?\u956 \'ec\u959 \'ef\u957 \'ed\u8057 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u953 \'e9\u957 \'ed\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7952 ?\u966 \'f6\u8055 ?\u956 \'ec\u949 \'e5\u961 \'f1\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24 ); \plain \f1\i\lang1033\fs24  inc.\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u920 \'c8\u949 \'e5\u8050 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u945 \'e1\u7988 ?\u964 \'f4\u953 \'e9\u949 \'e5\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u8049 ?\u957 \'ed\u964 \'f4\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u955 \'eb\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7936 ?\u947 \'e3\u945 \'e1\u952 \'e8\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u963 \'f3\u965 \'f5\u957 \'ed\u949 \'e5\u965 \'f5\u948 \'e4\u8057 ?\u954 \'ea\u949 \'e5\u953 \'e9\u963 \'f3\u8057 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u956 \'ec\u949 \'e5\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u961 \'f1\u8056 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u8052 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u963 \'f3\u8052 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u952 \'e8\u949 \'e5\u8055 ?\u945 \'e1\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u947 \'e3\u957 \'ed\u8061 ?\u963 \'f3\u953 \'e9\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u964 \'f4\u955 \'eb.\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  des.\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u920 \'c8\u949 \'e5\u8050 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u963 \'f3\u8059 ?\u957 \'ed\u948 \'e4\u961 \'f1\u945 \'e1\u956 \'ec\u8051 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u956 \'ec\u949 \'e5\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u961 \'f1\u8056 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u8118 ?\u963 \'f3\u945 \'e1\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7989 ?\u955 \'eb\u951 \'e7\u957 \'ed\plain \f1\lang1033\fs24   (!) \plain \f2\lang1032\fs24 \u7936 ?\u947 \'e3\u945 \'e1\u952 \'e8\u8053 ?\u957 \'ed,\plain \f1\lang1033\fs24   \plain \f3\lang1033\fs24 \u8005 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7952 ?\u963 \'f3\u964 \'f4\u953 \'e9\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u956 \'ec\u8182 ?\u957 \'ed\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24   (!) \plain \f2\lang1032\fs24 \u945 \'e1\u7988 ?\u964 \'f4\u953 \'e9\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u8049 ?\u957 \'ed\u964 \'f4\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u955 \'eb\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24 . Danach (in mangelhafter Orthographie): \plain \f2\lang1032\fs24 \u949 \'e5\u8016 ?\u954 \'ea\u945 \'e1\u961 \'f1\u953 \'e9\u963 \'f3\u964 \'f4\u959 \'ef\u8059 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u956 \'ec\u949 \'e5, \u920 \'c8\u949 \'e5\u8050 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u956 \'ec\u959 \'ef\u965 \'f5,\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u8005 ?\u964 \'f4\u953 \'e9\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7968