\endash  \plain \f1\scaps\lang1033\fs24 Krumbacher\plain \f1\lang1033\fs24 , S. 50, 88, 117. \endash  \plain \f1\scaps\lang1033\fs24 J. Schmidt\plain \f1\lang1033\fs24 , Des Basilius aus Achrida, Erzbischofs von Thessalonich, bisher unedierte Dialoge. Ein Beitrag zur Geschichte des griechischen Schismas, M\u252 \'fcnchen 1901, S. 24. \endash  \plain \f1\scaps\lang1033\fs24 Sp. Lampros \plain \f1\lang1033\fs24  (Hrsg.), \plain \f2\lang1032\fs24 \u928 \'d0\u945 \'e1\u955 \'eb\u945 \'e1\u953 \'e9\u959 \'ef\u955 \'eb\u8057 ?\u947 \'e3\u949 \'e5\u953 \'e9\u945 \'e1\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u928 \'d0\u949 \'e5\u955 \'eb\u959 \'ef\u960 \'f0\u959 \'ef\u957 \'ed\u957 \'ed\u951 \'e7\u963 \'f3\u953 \'e9\u945 \'e1\u954 \'ea\u8049 ?\plain \f1\lang1033\fs24 , I, Athen 1912-1923, S. <19>, <21>. \endash  \plain \f1\scaps\lang1033\fs24 Hartig\plain \f1\lang1033\fs24 , S\plain \f1\scaps\lang1033\fs24 . 89 (\plain \f1\lang1033\fs24  Anm. 4), 136, 242, 247, 368, 378\plain \f1\scaps\lang1033\fs24 .\plain \f1\lang1033\fs24   \endash  \plain \f1\scaps\lang1033\fs24 L. Petit\plain \f1\lang1033\fs24 , Documents relatifs au concile de Florence, II: \u338 \'8cuvres anticonciliaires de Marc d\rquote \u201 \'c9ph\u232 \'e8se, in: Patrologia Orientalis 17, Paris 1923, S. 415, <435>, <443>, <449>, <460>, <480>, <482>, <484> = \plain \f1\scaps\lang1033\fs24 Ders\plain \f1\lang1033\fs24 ., Marci Eugenici metropolitae Ephesi opera anti-unionistica (Concilium Florentinum, Documenta et scriptores, Ser. A, X 2), Rom 1977, S. 107, <127>, <135>, <141>, <152>, <172>, <174>, <176> (Hs. jeweils nur erw\u228 \'e4hnt). \endash  \plain \f1\scaps\lang1033\fs24 Ders.\plain \f1\lang1033\fs24 , Marc Eug\u233 \'e9nicos, in: Dictionnaire de th\u233 \'e9ologie catholique, IX, 2, Paris 1927, Sp. 1976, 1980 (Hs. jeweils erw\u228 \'e4hnt). \endash  \plain \f1\scaps\lang1033\fs24 Beck\plain \f1\lang1033\fs24 , Kirch