1032\fs24 \u7952 ?\u954 \'ea \u964 \'f4\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f3\lang1033\fs24 \u7937 ?\plain \f2\lang1032\fs24 \u947 \'e3\u8055 ?\u969 \'f9\u957 \'ed,\plain \f1\lang1033\fs24   \plain \f3\lang1033\fs24 \u8005 ?\plain \f2\lang1032\fs24 \u964 \'f4\u953 \'e9\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u961 \'f1\u8056 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u945 \'e1\u8166 ?\u964 \'f4\u945 \'e1\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u8048 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u948 \'e4\u959 \'ef\u947 \'e3\u956 \'ec\u945 \'e1\u964 \'f4\u953 \'e9\u954 \'ea\u8048 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u949 \'e5\u966 \'f6\u8049 ?\u955 \'eb\u945 \'e1\u953 \'e9\u945 \'e1\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u963 \'f3\u8059 ?\u956 \'ec\u966 \'f6\u969 \'f9\u957 \'ed\u945 \'e1\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u8004 ?\u957 \'ed\u964 \'f4\u945 \'e1\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\plain \f3\lang1033\fs24 \u8150 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u955 \'eb\u959 \'ef\u953 \'e9\u960 \'f0\u959 \'ef\plain \f3\lang1033\fs24 \u8150 ?\plain \f2\lang1032\fs24 \u962 \'f2\plain \f1\lang1033\fs24   \plain \f3\lang1033\fs24 \u7937 ?\plain \f2\lang1032\fs24 \u947 \'e3\u8055 ?\u959 \'ef\u953 \'e9\u962 \'f2\plain \f1\lang1033\fs24   \plain \f3\lang1033\fs24 \u7936 ?\plain \f2\lang1032\fs24 \u957 \'ed\u964 \'f4\u953 \'e9\u960 \'f0\u945 \'e1\u961 \'f1\u949 \'e5\u958 \'ee\u949 \'e5\u964 \'f4\u945 \'e1\u950 \'e6\u959 \'ef\u956 \'ec\u8051 ?\u957 \'ed\u951 \'e7\plain \f1\lang1033\fs24   \plain \f3\lang1033\fs24 \u7969 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u923 \'cb\u945 \'e1\u964 \'f4\u8055 ?\u957 \'ed\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u948 \'e4\u8057 ?\u958 \'ee\u945 \'e1\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u959 \'ef\plain \f3\lang1033\fs24 \u8016 ?\plain \f2\lang1032\fs24 \u967 \'f7\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u949 \'e5\plain \f3\lang1033\fs24 \u8017 ?\plain \f2\lang1032\fs24 \u961 \'f1\u8055 ?\u963 \'f3\u954 \'ea\u949 \'e5\u964 \'f4\u945 \'e1\u953 \'e9\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u963 \'f3\u8059 ?\u956 \'ec\u966 \'f6\u969 \'f9\u957 \'ed\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u945 \'e1\u8016 ?\u964 \'f4\u959 \'ef\u8150 ?\u962 \'f2,\plain \f1\lang1033\fs24   \plain \f3\lang1033\fs24 \u7936 ?\plain \f2\lang1032\fs24 \u955 \'eb\u955 \'eb\u8048 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u956 \'ec\u8118 ?\u955 \'eb\u955 \'eb\u959 \'ef\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u945 \'e1\u957 \'ed\u964 \'f4\u959 \'ef\u8055 ?\u8115 ?\plain \f1\lang1033\fs24\cf1  \plain \f2\lang1032\fs24 \u945 \'e1\plain \f3\lang1033\fs24 \u7985 ?\plain \f2\lang1032\fs24 \u961 \'f1\u8051 ?\u963 \'f3\u949 \'e5\u953 \'e9\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u963 \'f3\u8059 ?\u956 \'ec\u966 \'f6\u969 \'f9\u957 \'ed\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24   \plain \f3\lang1033\fs24 \u7956 ?\plain \f2\lang1032\fs24 \u958 \'ee\u969 \'f9\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u8000 ?\u961 \'f1\u952 \'e8\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u8134 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u949 \'e5\plain \f3\lang1033\fs24 \u8016 ?\plain \f2\lang1032\fs24 \u963 \'f3\u949 \'e5\u946 \'e2\u949 \'e5\u8055 ?\u945 \'e1\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u948 \'e4\u959 \'ef\u947 \'e3\u956 \'ec\u8049 ?\u964 \'f4\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24 ); \plain \f1\i\lang1033\fs24  inc.\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u922 \'ca\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24   \plain \f3\lang1033\fs24 \u8001 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u923 \'cb\u945 \'e1\u964 \'f4\u8150 ?\u957 \'ed\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u8048 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u961 \'f1\u949 \'e5\u8150 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u8017 ?\u960 \'f0\u959 \'ef\u963 \'f3\u964 \'f4\u8049 ?\u963 \'f3\u949 \'e5\u953 \'e9\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u8001 ?\u956 \'ec\u959 \'ef\u955 \'eb\u959 \'ef\u947 \'e3\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u8052 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u956 \'ec\u959 \'ef\u957 \'ed\u8049 ?\u948 \'e4\u945 \'e1\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u959 \'ef\u8016 ?\u954 \'ea\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7936 ?\u961 \'f1\u957 \'ed\u959 \'ef\u8059 ?\u956 \'ec\u949 \'e5\u957 \'ed\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u964 \'f4\u955 \'eb.\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  des. \plain \f2\lang1032\fs24 \u960 \'f0\u961 \'f1\u949 \'e5\u963 \'f3\u946 \'e2\u949 \'e5\u8055 ?\u945 \'e1\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u8134 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u952 \'e8\u949 \'e5\u959 \'ef\u964 \'f4\u8057 ?\u954 \'ea\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u8049 ?\u957 \'ed\u964 \'f4\u969 \'f9\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u8182 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7937 ?\u947 \'e3\u8055 ?\u969 \'f9\u957 \'ed\u183 \'b7\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7936 ?\u956 \'ec\u8053 ?\u957 \'ed\plain \f1\lang1033\fs24 , ed. \plain \f1\scaps\lang1033\fs24 Dositheus\plain \f1\lang1033\fs24   v. Jerusalem, \plain \f2\lang1032\fs24 \u932 \'d4\u8057 ?\u956 \'ec\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u964 \'f4\u945 \'e1\u955 \'eb\u955 \'eb\u945 \'e1\u947 \'e3\u8134 ?\u962 \'f2\plain \f1\lang1033\fs24 , Jassy 1692, S. 432-439 (mir nicht zug\u228 \'e4nglich; zitiert nach\plain \f1\scaps\lang1033\fs24  Beck\plain \f1\lang1033\fs24 , Kirche, S. 759). \endash  Kommentar (Argumente daf\u252 \'fcr, dass die katholische Lehre zum Ausgang des heiligen Geistes h\u228 \'e4retisch sei) intermittierend mit dem vollst\u228 \'e4ndigen Text des \plain \f1\b\lang1033\fs24  Maximus Confessor\plain \f1\lang1033\fs24   (PG 91, 145-149; CPG III 7697.13), der in zehn Kapitel (gez\u228 \'e4hlt am Rand \plain \f2\lang1032\fs24 \u945 \'e1\plain \f3\lang1033\fs24 \u8189 ?\plain \f1\lang1033\fs24   bis <\plain \f2\lang1032\fs24 \u953 \'e9\plain \f3\lang1033\fs24 \u8189 ?\plain \f1\lang1033\fs24  >) eingeteilt ist. \endash  \plain \f1\lang1033\fs22  Zum\plain \f1\lang1033\fs24   Text s. \plain \f1\scaps\lang1033\fs24 Ch. Patrineles\plain \f1\lang1033\fs24 , \plain \f2\lang1032\fs24 \u8190 ?\u927 \'cf\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u920 \'c8\u949 \'e5\u8057 ?\u948 \'e4\u969 \'f9\u961 \'f1\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u8127 ?\u913 \'c1\u947 \'e3\u945 \'e1\u955 \'eb\u955 \'eb\u953 \'e9\u945 \'e1\u957 \'ed\u8056 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u945 \'e1\u965 \'f5\u964 \'f4\u953 \'e9\u950 \'e6\u8057 ?\u956 \'ec\u949 \'e5\u957 \'ed\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u961 \'f1\u8056 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u8056 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u920 \'c8\u949 \'e5\u959 \'ef\u966 \'f6\u8049 ?\u957 \'ed\u951 \'e7\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u924 \'cc\u951 \'e7\u948 \'e4\u949 \'e5\u8055 ?\u945 \'e1\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u959 \'ef\u7985 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7936 ?\u957 \'ed\u8051 ?\u954 \'ea\u948 \'e4\u959 \'ef\u964 \'f4\u959 \'ef\u953 \'e9\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u955 \'eb\u8057 ?\u947 \'e3\u959 \'ef\u953 \'e9\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\u965 \'f5\plain \f1\lang1033\fs24 , Thessalonike 1978, S. 44-45 (ohne Kenntnis dieser Hs.); \plain \f1\scaps\lang1033\fs24 Demetrakopulus\plain \f1\lang1033\fs24   (s. \plain \f1\i\lang1033\fs24  Lit\plain \f1\lang1033\fs24 ), S. 108. }

