\pard\sl360\slmult1\fi0\li0\tx420\qj\ri0\sb0\sa0\itap0 \plain \f1\b\i\lang1033\fs24 Lit\plain \f1\lang1033\fs24  \tab \plain \f1\scaps\lang1033\fs24 Cbm Cat. 308\~c\plain \f1\lang1033\fs24 , Bd. I, S. 95. \endash  \plain \f1\scaps\lang1033\fs24 Hardt III, S. 95-96. \plain \f1\scaps\lang1033\fs24 \endash \plain \f1\scaps\lang1033\fs24  Hartig,\plain \f1\lang1033\fs24   S. 135, 186 (mit Anm. 11), 368, 378.\plain \f1\scaps\lang1033\fs24  \plain \f1\lang1033\fs24  \endash  \plain \f1\scaps\lang1033\fs24 Striedl\plain \f1\lang1033\fs24 , S. 120 (Anm. 140). \endash  \plain \f1\scaps\lang1033\fs24 Hajd\plain \f1\scaps\lang1033\fs24 \u250 \'fa\plain \f1\lang1033\fs24 , Sammlung, S. 36-37, 40 (Anm. 83), 60, 79-80, 94.}

