\u945 \'e1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u961 \'f1\u959 \'ef\u963 \'f3\u949 \'e5\u954 \'ea\u964 \'f4\u953 \'e9\u954 \'ea\u959 \'ef\u8058 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u959 \'ef\u8055 ?\u951 \'e7\u963 \'f3\u8131 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u961 \'f1\u8056 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u8052 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7936 ?\u954 \'ea\u961 \'f1\u8057 ?\u945 \'e1\u963 \'f3\u953 \'e9\u957 \'ed.\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7936 ?\u957 \'ed\u969 \'f9\u964 \'f4\u8051 ?\u961 \'f1\u969 \'f9\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u956 \'ec\u8050 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u959 \'ef\u8022 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u8052 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u949 \'e5\u961 \'f1\u8054 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\u8166 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7936 ?\u956 \'ec\u960 \'f0\u949 \'e5\u955 \'eb\u8182 ?\u957 \'ed\u959 \'ef\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u945 \'e1\u961 \'f1\u945 \'e1\u946 \'e2\u959 \'ef\u955 \'eb\u8052 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u959 \'ef\u8150 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7936 ?\u954 \'ea\u961 \'f1\u959 \'ef\u969 \'f9\u956 \'ec\u8051 ?\u957 \'ed\u959 \'ef\u953 \'e9\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7952 ?\u958 \'ee\u8051 ?\u952 \'e8\u951 \'e7(\u954 \'ea\u949 \'e5\u957 \'ed)\plain \f1\lang1033\fs24 , \plain \f2\lang1032\fs24 \u7952 ?\u957 \'ed\plain \f1\lang1033\fs24   \plain \f3\lang1033\fs24 \u8087 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7940 ?\u957 \'ed\u952 \'e8\u961 \'f1\