 \plain \f2\lang1032\fs24 \u954 \'ea\u964 \'f4\u955 \'eb.\plain \f1\lang1033\fs24   \plain \f1\i\lang1033\fs24  des.\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u8048 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u963 \'f3\u8053 ?\u956 \'ec\u949 \'e5\u961 \'f1\u959 \'ef\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7936 ?\u957 \'ed\u945 \'e1\u947 \'e3\u957 \'ed\u969 \'f9\u963 \'f3\u952 \'e8\u951 \'e7\u963 \'f3\u8057 ?\u956 \'ec\u949 \'e5\u957 \'ed\u945 \'e1\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u949 \'e5\u8016 ?\u945 \'e1\u947 \'e3\u947 \'e3\u949 \'e5\u955 \'eb\u953 \'e9\u954 \'ea\u8048 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u8165 ?\u8053 ?\u956 \'ec\u945 \'e1\u964 \'f4\u945 \'e1\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u960 \'f0\u945 \'e1\u961 \'f1\u945 \'e1\u963 \'f3\u964 \'f4\u8053 ?\u963 \'f3\u949 \'e5\u953 \'e9\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u963 \'f3\u945 \'e1\u966 \'f6\u8051 ?\u963 \'f3\u964 \'f4\u949 \'e5\u961 \'f1\u959 \'ef\u957 \'ed\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u959 \'ef\u8021 ?\u964 \'f4\u969 \'f9\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7956 ?\u967 \'f7\u959 \'ef\u957 \'ed\u964 \'f4\u945 \'e1\u903 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u8183 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u954 \'ea\u945 \'e1\u953 \'e9\u961 \'f1\u8183 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7952 ?\u954 \'ea\u949 \'e5\u8055 ?\u957 \'ed\u8179 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u7952 ?\u955 \'eb\u952 \'e8\u8057 ?\u957 \'ed\u964 \'f4\u953 \'e9\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u964 \'f4\u8183 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u8127 ?\u921 \'c9\u951 \'e7\u963 \'f3\u959 \'ef\u8166 ?\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u949 \'e5\u7984 ?\u962 \'f2\plain \f1\lang1033\fs24   \plain \f2\lang1032\fs24 \u922 \'ca\u945 \'e